def prepare():
 jobs=[]
 for rid,r in ROOMS.items():
  folder=ROOT/'assets/2d'/('T-041-'+r['name']);folder.mkdir(exist_ok=True);(folder/'prompts').mkdir(exist_ok=True)
  r['folder']=str(folder.relative_to(ROOT))
  for view,pos,target,desc in VIEWS[rid]:
   stem=f'{rid}_{view}-v3';prompt=STYLE+(AMB if rid=='amb_room' else CON)+' CAMERA AND REQUIRED COMPOSITION: '+desc
   (folder/'prompts'/f'{stem}.txt').write_text(prompt+'\n')
   jobs.append({'id':stem,'room':rid,'prompt':prompt,'output':str(folder/f'{stem}.png'),'camera':pos,'target':target,'status':'pending'})
 (OUT/'jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2))
 (OUT/'layout.json').write_text(json.dumps(ROOMS,ensure_ascii=False,indent=2))
if __name__=='__main__':prepare()
